<?php
function outpatientValue($value) { return htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8'); }
$filters = array('from_date' => isset($_GET['from_date']) ? $_GET['from_date'] : '', 'to_date' => isset($_GET['to_date']) ? $_GET['to_date'] : '', 'department_id' => isset($_GET['department_id']) ? $_GET['department_id'] : '', 'payer_type_id' => isset($_GET['payer_type_id']) ? $_GET['payer_type_id'] : '');
?>
<!DOCTYPE html>
<html lang="vi"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quản lý ngoại trú | CARE IOC</title><script src="https://cdn.tailwindcss.com"></script><link rel="stylesheet" href="https://unpkg.com/@phosphor-icons/web@2.1.1/src/regular/style.css"></head>
<body class="bg-slate-50 text-slate-700"><main class="max-w-7xl mx-auto px-4 py-8">
  <div class="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between mb-6"><div><a class="text-sm text-blue-600 hover:underline" href="<?php echo XC_URL; ?>/">← Quay lại tổng quan</a><h1 class="text-2xl font-bold text-slate-900 mt-1">Khám chữa bệnh ngoại trú</h1><p class="text-sm text-slate-500 mt-1">Nhập và theo dõi số liệu theo ngày, khoa/phòng, đối tượng thanh toán.</p></div><button onclick="openForm()" class="bg-blue-600 hover:bg-blue-700 text-white rounded-lg px-4 py-2.5 font-semibold"><i class="ph ph-plus"></i> Nhập số liệu</button></div>
  <?php if (!empty($flash['message'])): ?><div class="mb-5 rounded-lg border px-4 py-3 <?php echo $flash['type'] === 'success' ? 'border-emerald-200 bg-emerald-50 text-emerald-800' : 'border-red-200 bg-red-50 text-red-800'; ?>"><?php echo outpatientValue($flash['message']); ?></div><?php endif; ?>
  <section class="bg-white rounded-xl border border-slate-200 p-4 mb-5"><form class="grid grid-cols-1 md:grid-cols-5 gap-3" method="get"><label class="text-sm">Từ ngày<input type="date" name="from_date" value="<?php echo outpatientValue($filters['from_date']); ?>" class="mt-1 block w-full rounded-lg border-slate-300"></label><label class="text-sm">Đến ngày<input type="date" name="to_date" value="<?php echo outpatientValue($filters['to_date']); ?>" class="mt-1 block w-full rounded-lg border-slate-300"></label><label class="text-sm">Khoa/phòng<select name="department_id" class="mt-1 block w-full rounded-lg border-slate-300"><option value="">Tất cả</option><?php foreach ($departments as $item): ?><option value="<?php echo $item->id; ?>" <?php echo $filters['department_id'] == $item->id ? 'selected' : ''; ?>><?php echo outpatientValue($item->department_name); ?></option><?php endforeach; ?></select></label><label class="text-sm">Thanh toán<select name="payer_type_id" class="mt-1 block w-full rounded-lg border-slate-300"><option value="">Tất cả</option><?php foreach ($payerTypes as $item): ?><option value="<?php echo $item->id; ?>" <?php echo $filters['payer_type_id'] == $item->id ? 'selected' : ''; ?>><?php echo outpatientValue($item->payer_type_name); ?></option><?php endforeach; ?></select></label><div class="flex items-end gap-2"><button class="bg-slate-800 text-white px-4 py-2 rounded-lg">Lọc</button><a href="<?php echo XC_URL; ?>/outpatient" class="px-3 py-2 text-slate-600">Đặt lại</a></div></form></section>
  <section class="bg-white rounded-xl border border-slate-200 p-4 mb-5"><form method="post" enctype="multipart/form-data" class="flex flex-col sm:flex-row gap-3 sm:items-center"><input type="hidden" name="csrf" value="<?php echo outpatientValue($csrf); ?>"><input type="hidden" name="action" value="import"><div><b class="text-sm">Import Excel / CSV</b><p class="text-xs text-slate-500">Cột bắt buộc: report_date, department_id, payer_type_id. Có thể dùng tên/mã khoa và đối tượng thanh toán.</p></div><input type="file" name="import_file" accept=".xlsx,.csv" required class="text-sm"><button class="bg-emerald-600 text-white px-4 py-2 rounded-lg whitespace-nowrap">Import</button></form></section>
  <section class="bg-white rounded-xl border border-slate-200 overflow-x-auto"><table class="min-w-full text-sm"><thead class="bg-slate-100 text-slate-600"><tr><th class="p-3 text-left">Ngày</th><th class="p-3 text-left">Khoa/phòng</th><th class="p-3 text-left">Thanh toán</th><th class="p-3 text-right">Lượt khám</th><th class="p-3 text-right">Tái khám</th><th class="p-3 text-right">Chờ / khám</th><th class="p-3 text-right">Hoàn thành</th><th class="p-3 text-right">Chờ TB</th><th class="p-3 text-right">Thao tác</th></tr></thead><tbody class="divide-y divide-slate-100"><?php if (!$records): ?><tr><td colspan="9" class="p-8 text-center text-slate-500">Chưa có số liệu phù hợp.</td></tr><?php endif; foreach ($records as $record): ?><tr><td class="p-3 font-medium"><?php echo date('d/m/Y', strtotime($record->report_date)); ?></td><td class="p-3"><?php echo outpatientValue($record->department_name); ?></td><td class="p-3"><?php echo outpatientValue($record->payer_type_name); ?></td><td class="p-3 text-right"><?php echo number_format($record->visit_count); ?></td><td class="p-3 text-right"><?php echo number_format($record->revisit_count); ?></td><td class="p-3 text-right"><?php echo number_format($record->waiting_count); ?> / <?php echo number_format($record->examining_count); ?></td><td class="p-3 text-right"><?php echo number_format($record->completed_count); ?></td><td class="p-3 text-right"><?php echo $record->avg_wait_minutes === null ? '—' : outpatientValue($record->avg_wait_minutes) . ' phút'; ?></td><td class="p-3 whitespace-nowrap"><button type="button" onclick='editRecord(<?php echo json_encode($record, JSON_HEX_APOS | JSON_HEX_AMP | JSON_HEX_QUOT); ?>)' class="text-blue-600 mr-3">Sửa</button><form method="post" class="inline" onsubmit="return confirm('Xóa bản ghi này?')"><input type="hidden" name="csrf" value="<?php echo outpatientValue($csrf); ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?php echo $record->id; ?>"><button class="text-red-600">Xóa</button></form></td></tr><?php endforeach; ?></tbody></table></section>
</main>
<div id="modal" class="hidden fixed inset-0 bg-slate-900/50 p-4 overflow-y-auto"><div class="bg-white max-w-3xl mx-auto my-8 rounded-xl shadow-xl p-6"><div class="flex justify-between mb-5"><h2 id="form-title" class="text-lg font-bold">Nhập số liệu ngoại trú</h2><button onclick="closeForm()">✕</button></div><form method="post" id="record-form" class="grid grid-cols-1 md:grid-cols-3 gap-4"><input type="hidden" name="csrf" value="<?php echo outpatientValue($csrf); ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" id="id"><label class="text-sm font-medium">Ngày báo cáo<input required type="date" name="report_date" id="report_date" value="<?php echo date('Y-m-d'); ?>" class="mt-1 block w-full rounded-lg border-slate-300"></label><label class="text-sm font-medium">Khoa/phòng<select required name="department_id" id="department_id" class="mt-1 block w-full rounded-lg border-slate-300"><option value="">Chọn khoa/phòng</option><?php foreach ($departments as $item): ?><option value="<?php echo $item->id; ?>"><?php echo outpatientValue($item->department_name); ?></option><?php endforeach; ?></select></label><label class="text-sm font-medium">Đối tượng thanh toán<select required name="payer_type_id" id="payer_type_id" class="mt-1 block w-full rounded-lg border-slate-300"><option value="">Chọn đối tượng</option><?php foreach ($payerTypes as $item): ?><option value="<?php echo $item->id; ?>"><?php echo outpatientValue($item->payer_type_name); ?></option><?php endforeach; ?></select></label><?php foreach (array('visit_count' => 'Tổng lượt khám', 'revisit_count' => 'Lượt tái khám', 'waiting_count' => 'Đang chờ khám', 'examining_count' => 'Đang được khám', 'completed_count' => 'Đã hoàn thành', 'referral_count' => 'Chuyển tuyến') as $name => $label): ?><label class="text-sm font-medium"><?php echo $label; ?><input type="number" min="0" value="0" name="<?php echo $name; ?>" id="<?php echo $name; ?>" class="mt-1 block w-full rounded-lg border-slate-300"></label><?php endforeach; ?><label class="text-sm font-medium">Thời gian chờ TB (phút)<input type="number" min="0" step="0.01" name="avg_wait_minutes" id="avg_wait_minutes" class="mt-1 block w-full rounded-lg border-slate-300"></label><div class="md:col-span-3 text-right"><button type="button" onclick="closeForm()" class="px-4 py-2 text-slate-600">Hủy</button><button class="bg-blue-600 text-white px-4 py-2 rounded-lg">Lưu số liệu</button></div></form></div></div>
<script>const modal=document.getElementById('modal'), form=document.getElementById('record-form'); function openForm(){form.reset();document.getElementById('id').value='';document.getElementById('report_date').value=new Date().toISOString().slice(0,10);document.getElementById('form-title').textContent='Nhập số liệu ngoại trú';modal.classList.remove('hidden')} function closeForm(){modal.classList.add('hidden')} function editRecord(record){openForm();document.getElementById('form-title').textContent='Sửa số liệu ngoại trú'; Object.keys(record).forEach(key=>{const field=document.getElementById(key);if(field)field.value=key==='report_date'?record[key].slice(0,10):record[key]??''})}</script>
</body></html>
